  and i.id = t.institution_id
  and i.slug = 'umes';
update public.admission_stats t set notes = 'From the Common Data Set. GPA and waitlist numbers are not reported. No early decision; nonbinding early action. Only about 41% of enrollees sent SAT/ACT scores, so score ranges describe test submitters only.'
from public.institutions i
where t.institution_id = 'b78d08d2-3ed6-5eba-bdad-7888146c3bc7'
