  and i.id = t.institution_id
  and i.slug = 'umn';
update public.admission_stats t set notes = 'Average GPA 4.47 is a weighted GPA. Enrolled by residency: 4,063 in-state, 728 out-of-state, 300 international. The Common Data Set residency table is headed ''Fall 2024'' but its totals equal the Fall 2025 totals of the applications and admissions section. Early action closes Oct 15; no early decision.'
from public.institutions i
