  and t.cds_year = '2025-2026'
  and i.id = t.institution_id
  and i.slug = 'unc';
update public.admission_stats t set notes = 'Fall 2025 first-time first-year cohort, from the Common Data Set residency table (in-state / out-of-state / nonresident: 18,398 / 8,106 / 714 applied; 15,202 / 5,419 / 549 admitted; 4,305 / 497 / 132 enrolled). Only 16% of enrollees sent SAT scores and 27% sent ACT scores, so the score percentiles describe part of the class. The GPA breakdown is the ''all enrolled students'' column. Undergraduate enrollment is the total undergraduates (13,380 men + 12,833 women); the number of international undergraduates is the nonresident total (700). Early action exists (closes Nov 1); no early decision and no waitlist.'
from public.institutions i
where t.institution_id = 'cc9f05d8-5e03-50e1-8d55-494b90189707'
  and t.cds_year = '2025-2026'
  and i.id = t.institution_id
