  and i.slug = 'hawaii-hilo';
update public.cost_aid t set notes = 'HPU 2026-27 cost of attendance, independent undergraduate, non-nursing (nursing tuition is $44,616). Food and housing is an estimate; other costs are personal $1,800 + transportation $2,600 + loan fees $132. No separate international tuition rate is listed; HPU says international scholarships cover up to 50% of tuition. International first-year and transfer applicants are considered for academic merit scholarships automatically at admission (no separate application; no amounts are published). Talent (vocal ensemble, band, orchestra, E-Sports) and athletic scholarships also exist. The Guaranteed Scholarship and Admission Program ($15,000/yr) is only for Hawaii high school seniors. International need-based aid is not mentioned.'
