update public.cost_aid t set notes = 'College Scorecard (IPEDS 2023-24): tuition includes required fees; on-campus cost of attendance; International students are not eligible for aid through FAFSA. All admitted international students are automatically considered for the MSU Non-resident Scholarship ($3,000 to $18,000 a year, award levels by academic performance; decisions by mid-February); applying by Nov 1 gives maximum consideration.'
