  and t.year = '2026-2027'
  and i.id = t.institution_id
  and i.slug = 'minot-state';
update public.cost_aid t set notes = 'College Navigator (IPEDS) 2024-25: tuition includes required fees; on-campus cost of attendance for out-of-state students is $48,148. MSU''s own current tuition page was not read, so current-year figures may differ; Non-resident academic scholarship is awarded automatically on admission by 9th-11th grade GPA, renewable up to 4 years (fall 2027 entrants): $12,000/yr at 3.30-3.59, $16,000/yr at 3.60-4.09, $19,000/yr at 4.10+. Competitive awards (e.g. Maroon and White) need the General Scholarship Application and qualifying SAT/ACT by Dec. 1. Students with active agent contracts are ineligible. Need-based aid for internationals is not mentioned.'
from public.institutions i
where t.institution_id = '90f9a1f6-6c35-50ac-a4d0-0ec62e5f8c12'
  and t.year = '2024-2025'
