where t.institution_id = 'b94f5f29-b306-56ea-a3f0-816912446970'
  and t.year = '2026-2027'
  and i.id = t.institution_id
  and i.slug = 'morgan-state';
update public.cost_aid t set notes = 'Tuition is $13,609 per semester (General Studies, doubled to a year); Health Studies $14,773 and Nursing $15,382 per semester. Comprehensive fee $752 per semester. Resident students must buy a meal plan: shared-room housing plus meals runs $5,465 to $7,777 per semester, so housing and food is not shown. The total cost of attendance shown is the college''s on-campus budget for most majors (Health Studies $52,560, Nursing $53,778). The page does not give a separate international tuition rate. Housing is mandatory for traditional-age full-time international students; The scholarships page says full-time international students living on campus are eligible for a $17,000 International Grant plus a $2,000 Residence Hall Grant, and those living off campus receive a $12,000 International Grant; the page does not say whether the International Grant is per year (the Residence Hall Grant is described as $2,000 a year). Separate academic awards for new full-time students are set by high school GPA (up to $16,000 to $44,000 over four years). A search-engine snippet of the same page showed older figures ($15,000, $3,000 and $11,000), so confirm current amounts with admissions. Eligible non-citizens with an Alien Registration Number or permanent residency can file the FAFSA; other international students are not eligible for federal aid. Need-based aid for international students is not stated.'
from public.institutions i
where t.institution_id = 'e05eccef-f5c4-52d0-a47c-2dd7755fb89f'
  and t.year = '2026-2027'
  and i.id = t.institution_id
  and i.slug = 'mount-aloysius';
update public.cost_aid t set notes = '2026-27 catalog, first-year students: full-time tuition $46,500 per year (12-18 credits a term; $1,350 per credit part-time); room and board $16,200 (shared occupancy); technology fee $800, student activity fee $420 and academic service fee $700 (required fees are their sum). Student health insurance $3,006 is required unless waived with proof of coverage. Program costs average $1,000 a year for texts and supplies. The catalog does not print a total cost of attendance; International applicants are reviewed for merit scholarships the same way as domestic ones: the International Student Merit Scholarship is awarded at acceptance (four years for first-year students) based on cumulative GPA and standardized test scores, renewable with a 3.2 GPA. The amount is not published for international students; the Tuition/Fees page says merit scholarships in general range from $17,000 to $30,000 per year. Premier Programs offer full-tuition or room-and-board awards. Federal aid (FAFSA) does not apply to international students.'
from public.institutions i
