  and t.cycle = '2026-27'
  and i.id = t.institution_id
  and i.slug = 'wright-state';
update public.test_policies t set notes = 'The freshman page says Xavier is test-optional (it describes the policy in pandemic terms, so confirm it still applies); applicants who do not submit SAT/ACT must submit an essay and resume instead. The Common Data Set says test scores are required for students with a GPA below 3.0. The page states there is no minimum GPA or test score for admission.'
from public.institutions i
